<?php
namespace App\Controllers;
use App\Core\{Database,Response};
use App\Services\SubscriptionService;
final class ApiController {
    private function token():array{$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/^Bearer\s+(.+)$/i',$h,$m))Response::json(['success'=>false,'message'=>'Bearer token required'],401);$hash=hash('sha256',$m[1]);$db=Database::connection();$s=$db->prepare("SELECT a.*,u.status user_status,t.status tenant_status FROM api_tokens a JOIN users u ON u.id=a.user_id AND u.tenant_id=a.tenant_id JOIN tenants t ON t.id=a.tenant_id WHERE a.token_hash=? AND a.revoked_at IS NULL AND (a.expires_at IS NULL OR a.expires_at>NOW()) LIMIT 1");$s->execute([$hash]);$x=$s->fetch();if(!$x||$x['user_status']!=='active'||$x['tenant_status']!=='active')Response::json(['success'=>false,'message'=>'Invalid token'],401);if(!SubscriptionService::featureEnabled((int)$x['tenant_id'],'api'))Response::json(['success'=>false,'message'=>'API is not enabled for this subscription'],403);$db->prepare("UPDATE api_tokens SET last_used_at=NOW() WHERE id=?")->execute([$x['id']]);return $x;}
    public function resource(string $resource):never{$a=$this->token();$map=['customers'=>['customers','deleted_at IS NULL','name'],'jobs'=>['jobs','deleted_at IS NULL','id DESC'],'assets'=>['customer_assets','deleted_at IS NULL','id DESC'],'inventory'=>['items','deleted_at IS NULL','item_name'],'invoices'=>['invoices','deleted_at IS NULL','id DESC']];if(!isset($map[$resource]))Response::json(['success'=>false,'message'=>'Unknown resource'],404);[$table,$where,$order]=$map[$resource];$db=Database::connection();$s=$db->prepare("SELECT * FROM {$table} WHERE tenant_id=? AND {$where} ORDER BY {$order} LIMIT 500");$s->execute([$a['tenant_id']]);Response::json(['success'=>true,'data'=>$s->fetchAll()]);}
}
